"""HORIZON: authored finale, bilingual clues, reproducible geometry and routes."""
from chapter4_layout import *
from itertools import product, permutations

P = pair
def opts(values): return [tr(*v) for v in values]
def clicks(target): return [i for i,n in enumerate(target) for _ in range(n)]

class FinaleLevel(Level):
 def __init__(self,n,title,layout,intro,outro):
  super().__init__(n,title,layout[0],intro,outro)
  self.layout_en=layout[1];self.rng=random.Random(19000+n)
 def puzzle(self,k,cell,title,mode,rules,method,solution,actions,**kw):
  e=super().puzzle(k,cell,title,rules,mode,[P('Lisez les deux consignes du secteur. Les règles complètes figurent aussi sur ce poste.','Read both sector instructions. This station also contains all rules.'),method],solution,actions,**kw)
  e['puzzle_type']=e['model']='finale';return e
 def notes(self,k,positions,texts):
  for i,(pos,txt) in enumerate(zip(positions,texts)):
   self.clue('n'+str(2*k-1+i),pos,(k+1)*100+1+i,P('Consigne '+str((k+1)*100+1+i),'Instruction '+str((k+1)*100+1+i)),txt)

# 21: a long gantry spine, three inspection bays and two distinct service wings.
l=FinaleLevel(21,P('Le département des petites précautions','The department of minor precautions'),P('Une épine de maintenance longe trois baies de silos. Les ponts A/B/C donnent accès aux inspections. Le sas 111 conduit à la comptabilité au nord-est, le sas 112 au retour des capsules au sud-est.','A maintenance spine runs beside three silo bays. Bridges A/B/C lead to inspections. Gate 111 leads to accounting in the northeast; gate 112 to capsule returns in the southeast.'),P('HORIZON. Derrière les silhouettes aperçues au conseil, des fusées occupent des hangars entiers. PATIENCE. TENDRESSE. MODÉRATION. « Trois petites précautions. Nous avions prévu davantage de modération, mais le plafond était trop bas. » Le bon de fabrication porte le numéro de votre dernière validation.','HORIZON. Behind the silhouettes glimpsed at the council, rockets occupy entire hangars. PATIENCE. TENDERNESS. MODERATION. “Three minor precautions. We planned more moderation, but the ceiling was too low.” The manufacturing order bears your last approval number.'),P('Le registre distingue deux listes : les habitants conformes, à conserver sous terre ; les « variables extérieures », à traiter par HORIZON. Les pièces que vous avez validées alimentaient cette entreprise. Une ligne a été barrée au crayon : RETOUR. Vous rétablissez au moins celui des capsules d’essai.','The ledger separates compliant residents, to be kept underground, from “outside variables”, to be handled by HORIZON. The parts you approved served this enterprise. One line was crossed out in pencil: RETURN. You have restored it for the test capsules, at least.'))
