for i,y in enumerate([5,17,29]):
 e=l.clue('obs'+str(i),(17,y),210+i,P('Inspection '+ 'ABC'[i],'Inspection '+ 'ABC'[i]),[P('PATIENCE : capacité de cinq caisses-unités. Le dossier de poids 3 lui est affecté. Aucun équipement réel ne figure sur ce manifeste : seulement des formulaires.','PATIENCE: capacity five crate-units. The weight-3 file is assigned here. This manifest contains paperwork only.'),P('TENDRESSE : capacité cinq. La caisse de poids 1 accompagne celle de poids 4. Les caisses ne peuvent être divisées.','TENDERNESS: capacity five. The weight-1 crate accompanies weight 4. Crates cannot be split.'),P('MODÉRATION : capacité six. Le dossier de poids 6 voyage seul. Le coût du formulaire dépasse celui de son contenu.','MODERATION: capacity six. The weight-6 file travels alone. The form costs more than its contents.')][i]);obs.append(e['id'])
l.notes(1,[(1,1),(3,33)],[P('Les trois ponts tournent sur trois crans : 0 est aligné, 1 et 2 sont fermés. I déplace A et B ; II déplace B et C ; III déplace A et C. Les flèches inverses annulent un cran.','Bridges have three positions: 0 aligned; 1 and 2 closed. I moves A and B; II moves B and C; III moves A and C. Reverse arrows undo a step.'),P('Départ A=1, B=2, C=0. Alignez les trois ponts, visitez les inspections 210/211/212, puis revenez certifier au poste 203. Les ponts ne se commandent qu’ici.','Start A=1, B=2, C=0. Align all bridges, visit inspections 210/211/212, then return to certify at 203. Bridges can only be operated here.')])
gantry=l.puzzle(1,(9,17),P('Trois ponts pour une petite signature','Three bridges for one small signature'),'gantry',P('Installer la mallette. Trois crans par pont ; 0 ouvre le passage. I agit sur A+B, II sur B+C, III sur A+C. Aligner les trois, lire 210/211/212 et revenir valider. Départ : 1/2/0.','Install the kit. Three positions per bridge; 0 opens it. I affects A+B, II B+C, III A+C. Align all three, read 210/211/212 and return to validate. Start: 1/2/0.'),P('Un cran après 2 revient à 0. Choisissez les mouvements par leurs effets communs ; une flèche inverse permet toujours de revenir.','One step after 2 returns to 0. Use the shared effects; a reverse arrow always lets you undo.'),P('II une fois, III deux fois : A/B/C = 0/0/0. Lire 210, 211, 212 puis revenir à 203 et valider.','II once, III twice: A/B/C = 0/0/0. Read 210, 211, 212, return to 203 and validate.'),[1,2,2],initial=[1,2,0],masks=[[1,1,0],[0,1,1],[1,0,1]],observations=obs,world_gates=[dict(cell=[13,y],channel=i,allowed=[0],label='ABC'[i]) for i,y in enumerate([5,17,29])])
l.notes(2,[(23,1),(33,15)],[P('Répartir une fois chacune les caisses 1, 2, 3, 4 et 6 entre PATIENCE (5), TENDRESSE (5) et MODÉRATION (6). Aucun reste au dépôt.','Assign each crate 1, 2, 3, 4 and 6 once to PATIENCE (5), TENDERNESS (5) and MODERATION (6). Leave none in storage.'),P('Le relevé A affecte 3 à PATIENCE. Le relevé B groupe 1 avec 4. Le relevé C isole 6. Les capacités sont exactes.','Record A assigns 3 to PATIENCE. Record B groups 1 with 4. Record C isolates 6. Capacities are exact.')])
l.puzzle(2,(29,9),P('Le poids de la paperasse','The weight of paperwork'),'manifest',P('Caisses indivisibles 1/2/3/4/6 ; capacités exactes P=5, T=5, M=6. La caisse 3 va à P ; 1 accompagne 4 ; 6 reste seule. Toutes les caisses doivent quitter le dépôt.','Indivisible crates 1/2/3/4/6; exact capacities P=5, T=5, M=6. Crate 3 goes to P; 1 accompanies 4; 6 stays alone. All crates must leave storage.'),P('Six remplit MODÉRATION. Le duo 1+4 remplit TENDRESSE ; 2 complète le dossier 3 dans PATIENCE.','Six fills MODERATION. The 1+4 pair fills TENDERNESS; 2 completes 3 in PATIENCE.'),P('1 → TENDRESSE ; 2 → PATIENCE ; 3 → PATIENCE ; 4 → TENDRESSE ; 6 → MODÉRATION. Valider.','1 → TENDERNESS; 2 → PATIENCE; 3 → PATIENCE; 4 → TENDERNESS; 6 → MODERATION. Validate.'),clicks([2,1,1,2,3]),weights=[1,2,3,4,6],capacities=[5,5,6],labels=opts([(f'Caisse {i}',f'Crate {i}') for i in [1,2,3,4,6]]),choices=[opts([('Dépôt','Storage'),('PATIENCE','PATIENCE'),('TENDRESSE','TENDERNESS'),('MODÉRATION','MODERATION')])]*5)
