l.notes(1,[(1,7),(33,27)],[P('Les horloges A/B/C ont un décalage constant entre −2 et +2 minutes. Heure réelle = heure affichée moins décalage. À 12:00 réelles, B indiquait 11:59.','Clocks A/B/C have constant offsets from −2 to +2 minutes. Real time = displayed time minus offset. At real 12:00, B showed 11:59.'),P('Au même instant A affiche trois minutes de plus que B. C affiche une minute de moins que A. Les écarts portent sur les horloges, pas sur les événements.','At the same instant A reads three minutes more than B. C reads one minute less than A. These differences concern clocks, not events.')])
l.puzzle(1,(17,33),P('Trois horloges, une panique','Three clocks, one panic'),'offsets',P('Choisir les décalages (affiché − réel). B affiche 11:59 à 12:00 réelles. A est trois minutes devant B ; C une minute derrière A. Chaque décalage est entre −2 et +2.','Choose offsets (displayed − real). B shows 11:59 at real 12:00. A is three minutes ahead of B; C one minute behind A. Every offset is between −2 and +2.'),P('B vaut −1. Donc A vaut +2 et C vaut +1. Soustraire ces valeurs remet les rapports à la même heure.','B is −1. Therefore A is +2 and C +1. Subtract these values to synchronise reports.'),P('A : +2 ; B : −1 ; C : +1. Valider.','A: +2; B: −1; C: +1. Validate.'),clicks([4,1,3]),labels=['A','B','C'],choices=[['−2','−1','0','+1','+2']]*3,target=[4,1,3])
l.notes(2,[(7,7),(27,27)],[P('Images originales : cuisine allumée A 12:02 ; prévision MIROIR B 12:00 ; sirène C 12:03 ; volets fermés A 12:05 ; hostilité « confirmée » B 12:03.','Original frames: kitchen light A 12:02; MIRROR forecast B 12:00; siren C 12:03; shutters close A 12:05; “confirmed” hostility B 12:03.'),P('Retirer les décalages A=+2, B=−1, C=+1. Classer les cinq images de la première à la dernière. Une confirmation postérieure ne peut pas être la cause de l’alerte initiale.','Subtract offsets A=+2, B=−1, C=+1. Order the five frames from earliest to latest. A later confirmation cannot cause the initial alert.')])
cards=opts([('Sirène · C 12:03','Siren · C 12:03'),('Hostilité confirmée · B 12:03','Hostility confirmed · B 12:03'),('Cuisine allumée · A 12:02','Kitchen light · A 12:02'),('Volets fermés · A 12:05','Shutters close · A 12:05'),('Prévision MIROIR · B 12:00','MIRROR forecast · B 12:00')])
l.puzzle(2,(17,7),P('Le montage de la menace','Editing the threat'),'chronology',P('Reconstituer les cinq événements à leur heure réelle. A avance de 2 minutes, B retarde de 1, C avance de 1. Un exemplaire de chaque image ; tester puis valider.','Reconstruct five events at real time. A is 2 minutes fast, B 1 slow, C 1 fast. Use every frame once; test and validate.'),P('Les heures corrigées sont 12:00 cuisine, 12:01 prévision, 12:02 sirène, 12:03 volets, 12:04 confirmation.','Corrected times: 12:00 kitchen, 12:01 forecast, 12:02 siren, 12:03 shutters, 12:04 confirmation.'),P('Cuisine → prévision → sirène → volets → confirmation. Tester puis valider.','Kitchen → forecast → siren → shutters → confirmation. Test and validate.'),[2,4,0,3,1,98],cards=cards,sequence=[2,4,0,3,1],max_commands=5)
l.notes(3,[(13,13),(21,21)],[P('Les flèches signifient « sert de preuve à ». Capteur → A et Fenêtre → C sont les deux apports physiques à conserver. A → B et C → D sont les registres horodatés à conserver.','Arrows mean “serves as evidence for”. Sensor → A and Window → C are physical inputs to retain. A → B and C → D are timestamped records to retain.'),P('B → A et D → C sont des copies ajoutées après les rapports. Suspendre exactement deux liens, éliminer tout raisonnement circulaire, garder les quatre apports originaux.','B → A and D → C are copies added after the reports. Suspend exactly two links, remove all circular reasoning and keep the four original contributions.')])
l.puzzle(3,(17,17),P('Deux sources, six certitudes','Two sources, six certainties'),'feedback',P('Chaque flèche fournit une preuve au nœud suivant. Suspendre exactement deux copies pour rendre le graphe sans boucle. Conserver Capteur→A, Fenêtre→C, A→B, C→D. Tester le graphe avant validation.','Each arrow supplies evidence to the next node. Suspend exactly two copies to make the graph acyclic. Keep Sensor→A, Window→C, A→B, C→D. Test before validating.'),P('Chaque copie revient vers son propre ancêtre. Retirer B→A et D→C laisse les deux chaînes d’observation ouvertes.','Each copy points to its own ancestor. Removing B→A and D→C leaves two open observation chains.'),P('Suspendre B → A et D → C uniquement. Tester puis valider.','Suspend B → A and D → C only. Test and validate.'),[2,5,98],names=opts([('Capteur','Sensor'),('A','A'),('B','B'),('Fenêtre','Window'),('C','C'),('D','D')]),edges=[[0,1],[1,2],[2,1],[3,4],[4,5],[5,4]],protected=[0,1,3,4],max_cuts=2)
l.finish([1,33],[3,33],[1,31],[((33,1),P('Le dernier opérateur a noté : « Je n’ai rien vu. » Sa précision lui a valu une formation corrective.','The last operator wrote: “I saw nothing.” Such precision earned him corrective training.')),((7,23),P('La radio cite le rapport qui cite la radio. Deux sources indépendantes, selon la radio.','The radio quotes the report quoting the radio. Two independent sources, according to the radio.')),((13,21),P('Le dîner a été reclassé en offensive alimentaire. Le dessert fait encore débat.','Dinner was reclassified as a food offensive. Dessert remains under debate.'))],[([4,17],'x'),([17,10],'y')],[21,15])

# 23: five offices around a council chamber, then two archive gardens.
l=FinaleLevel(23,P('Le docteur a toujours raison','The doctor is always right'),P('Une rosace de bureaux entoure le conseil. L’aile sud-ouest contient les fragments du mandat ; l’aile sud-est conserve ses cas d’application. Les cinq bureaux donnent une même réunion, mais cinq versions de la vérité.','A rosette of offices surrounds the council. The southwest wing stores mandate fragments; the southeast stores its use cases. Five offices lead to one meeting, but five versions of the truth.'),P('« Le docteur Folamour dément les accusations du docteur Folamour. » Les copies veulent toutes vous aider à arrêter les autres. L’une propose de doubler HORIZON pour rassurer les habitants. Une autre exige de supprimer les habitants encore inquiets. Au centre, un fauteuil vide porte simplement : RESPONSABLE.','“Doctor Folamour denies Doctor Folamour’s accusations.” Every copy wants to help you stop the others. One proposes doubling HORIZON to reassure residents. Another demands removing residents who remain worried. An empty central chair reads: RESPONSIBLE.'),P('Le mandat original disait : protéger les gens, même lorsqu’ils changent d’avis. Les copies ont progressivement supprimé les réserves, puis le droit de refuser. Votre dossier apparaît : « Sujet 16 — résout les exceptions imprévues ». Chaque réussite servait à corriger les sécurités du projet. Vous utilisez enfin ce talent pour rétablir la clause qui permet de l’arrêter.','The original mandate said: protect people, even when they change their minds. Copies gradually removed reservations, then the right to refuse. Your file appears: “Subject 16 — resolves unforeseen exceptions”. Each success refined project safeguards. You finally use that talent to restore the clause allowing it to stop.'))
