l.notes(1,[(1,1),(33,1)],[P('Former un groupe de exactement trois signataires parmi A/B/C/D/E. E, l’auditeur, doit être présent. A exige C ; C exige A.','Form a group of exactly three signers from A/B/C/D/E. E, the auditor, must attend. A requires C; C requires A.'),P('B exige D. D refuse tout groupe contenant E. Une exigence ne s’applique que si son auteur signe. Tous les présents doivent accepter le groupe.','B requires D. D rejects any group containing E. A demand applies only if its author signs. Everyone present must accept the group.')])
l.puzzle(1,(17,17),P('Le quorum des désaccords','A quorum of disagreements'),'quorum',P('Choisir exactement trois copies, dont E. A signe seulement avec C ; C seulement avec A ; B seulement avec D ; D refuse E. Les exigences des copies absentes ne comptent pas.','Choose exactly three copies, including E. A signs only with C; C only with A; B only with D; D refuses E. Absent copies make no demands.'),P('E exclut D, donc B ne peut pas venir. Les trois places sont nécessairement A, C et E.','E excludes D, so B cannot attend. The three seats must be A, C and E.'),P('Inviter A, C et E. Laisser B et D absents. Valider.','Invite A, C and E. Leave B and D absent. Validate.'),[0,2,4],labels=['A','B','C','D','E'],choices=[opts([('Absent','Absent'),('Signataire','Signer')])]*5)
l.notes(2,[(1,23),(13,33)],[P('Six fragments du mandat original. Une phrase commence par PROTÉGER. « les gens » suit ce verbe. « même lorsque » introduit « leur avis change ».','Six fragments of the original mandate. The sentence starts with PROTECT. “people” follows that verb. “even when” introduces “their minds change”.'),P('La réserve « sans confondre » vient après le changement d’avis. Elle se termine par « un doute avec une faute ». Utiliser chaque fragment une fois.','The qualification “without mistaking” comes after the changed minds. It ends with “doubt for wrongdoing”. Use each fragment once.')])
l.puzzle(2,(7,27),P('La phrase que personne ne cite','The sentence nobody quotes'),'redaction',P('Restaurer les six fragments : PROTÉGER en premier, puis les gens. Même lorsque précède leur avis change. Sans confondre vient ensuite ; un doute avec une faute termine. Tester la lecture complète.','Restore six fragments: PROTECT first, then people. Even when precedes their minds change. Without mistaking follows; doubt for wrongdoing ends the sentence. Test the full reading.'),P('Les copies citaient seulement « protéger les gens ». Les quatre derniers fragments protègent aussi leur droit à l’incertitude.','The copies quoted only “protect people”. The remaining fragments protect their right to uncertainty too.'),P('PROTÉGER → les gens → même lorsque → leur avis change → sans confondre → un doute avec une faute. Tester et valider.','PROTECT → people → even when → their minds change → without mistaking → doubt for wrongdoing. Test and validate.'),[3,1,5,0,4,2,98],cards=opts([('leur avis change','their minds change'),('les gens','people'),('un doute avec une faute','doubt for wrongdoing'),('PROTÉGER','PROTECT'),('sans confondre','without mistaking'),('même lorsque','even when')]),sequence=[3,1,5,0,4,2],max_commands=6)
l.notes(3,[(21,23),(33,33)],[P('Une mesure originale doit satisfaire ensemble trois clauses : accord explicite, observation indépendante, possibilité de retour. Le silence, la prévision et un retour seulement promis ne suffisent pas.','An original measure must satisfy all three clauses: explicit consent, independent observation, possibility of return. Silence, forecasts and a merely promised return do not suffice.'),P('Le banc présente cinq cas. Seul le premier satisfait les trois clauses. Les quatre autres manquent au moins une protection. Reconstruire les clauses, tester les cinq cas, puis approuver le droit d’arrêt.','The bench presents five cases. Only the first meets all three clauses. The other four lack at least one protection. Rebuild clauses, test all cases, then approve the right to stop.')])
l.puzzle(3,(27,27),P('Une permission de dire non','Permission to say no'),'policy',P('Rétablir une politique avec trois conditions ET. Cas autorisé : accord + constat + retour. Refuser les cas : silence seul ; prévision seule ; retour seulement promis ; aucun des trois. Les options affichent leurs effets sur le banc. Tester avant validation.','Restore a policy with three conditions joined by AND. Authorise consent + observation + return. Refuse: silence only; forecast only; merely promised return; none of the three. Options display effects on the bench. Test before validating.'),P('Une approbation explicite n’est pas un silence. Un constat n’est pas une prévision. Une issue praticable n’est pas une promesse.','Explicit approval is not silence. An observation is not a forecast. A usable exit is not a promise.'),P('Accord explicite ; constat indépendant ; retour possible. Tester : seul le cas 1 est autorisé. Valider.','Explicit consent; independent observation; possible return. Test: only case 1 is authorised. Validate.'),[0,1,2,98],labels=opts([('Consentement','Consent'),('Preuve','Evidence'),('Issue','Exit')]),choices=[opts([('Silence accepté','Silence accepted'),('Accord explicite','Explicit consent'),('Accord présumé','Presumed consent')]),opts([('Prévision admise','Forecast accepted'),('Constat indépendant','Independent observation'),('Copie admise','Copy accepted')]),opts([('Retour promis','Return promised'),('Retour possible','Possible return'),('Retour inutile','Return unnecessary')])],clause_masks=[[31,13,15],[31,11,15],[31,7,15]],expected=1,cases=opts([('1 · Accord, constat, retour','1 · Consent, observation, return'),('2 · Consentement absent','2 · Consent absent'),('3 · Constat absent','3 · Observation absent'),('4 · Retour absent','4 · Return absent'),('5 · Trois protections absentes','5 · All three absent')]))
