l.notes(1,[(13,1),(1,13)],[P('Le simulateur part avec les copies actives et le secours armé. Photographier les réglages ne change rien. Suspendre les copies exige cette photographie. Isoler le secours exige les copies suspendues.','The simulator starts with copies active and backup armed. Photographing settings changes nothing. Suspending copies requires that photograph. Isolating backup requires suspended copies.'),P('L’arrêt exige le secours isolé. Sceller le droit d’arrêt exige que l’arrêt soit déjà confirmé. Tester une suite ne commande pas HORIZON ; seule la validation applique la procédure vérifiée.','Stopping requires isolated backup. Sealing the right to stop requires a confirmed stop. Testing a sequence does not control HORIZON; only validation applies the verified procedure.')])
l.puzzle(1,(11,11),P('Annuler l’annulation automatique','Cancel automatic cancellation'),'protocol',P('Programmer cinq opérations. Photographier précède suspendre les copies ; suspendre précède isoler le secours ; isoler précède arrêter ; arrêter précède sceller. Le simulateur explique le premier refus. Tester puis appliquer.','Program five operations. Photograph before suspending copies; suspend before isolating backup; isolate before stopping; stop before sealing. The simulator explains the first refusal. Test and apply.'),P('Conserver une trace permet de suspendre les copies. Retirer ensuite le mécanisme qui réannule les arrêts, puis arrêter et protéger la décision.','Preserve a record to suspend copies. Then remove the mechanism that recancels stops, stop, and protect the decision.'),P('Photographier → suspendre les copies → isoler le secours → arrêter → sceller. Tester puis valider.','Photograph → suspend copies → isolate backup → stop → seal. Test and validate.'),[2,4,1,0,3,98],cards=opts([('Arrêter','Stop'),('Isoler le secours','Isolate backup'),('Photographier les réglages','Photograph settings'),('Sceller le droit d’arrêt','Seal the right to stop'),('Suspendre les copies','Suspend copies')]),dependencies=[[1],[4],[],[0],[2]],max_commands=5)
l.notes(2,[(17,1),(33,15)],[P('Six relais de reprise sont actifs. Un levier inverse ses relais : I agit sur A/B/D ; II sur B/C/E ; III sur A/C/F ; IV sur C/D. Une même action deux fois s’annule.','Six retry relays are active. A lever flips its relays: I affects A/B/D; II B/C/E; III A/C/F; IV C/D. The same action twice cancels itself.'),P('Tous les relais doivent être éteints. Observez les six états, pas seulement la somme. On peut manœuvrer sans limite et réinitialiser. Tester certifie l’état courant seulement.','All relays must be off. Observe all six states, not just the total. Unlimited moves and reset are available. A test certifies only the current state.')])
l.puzzle(2,(25,9),P('Le secours du secours','The backup’s backup'),'damping',P('Départ : A/B/C/D/E/F actifs. I inverse A/B/D ; II B/C/E ; III A/C/F ; IV C/D. Éteindre les six. Un second appui annule le premier. Tester puis valider.','Start: A/B/C/D/E/F active. I flips A/B/D; II B/C/E; III A/C/F; IV C/D. Turn all six off. A second press undoes the first. Test and validate.'),P('I et II ensemble éteignent A/C/D/E, mais B est inversé deux fois. Avec III, les trois premiers retrouvent leur état. Cherchez plutôt une combinaison qui touche chaque relais un nombre impair de fois.','I and II together turn off A/C/D/E, while B flips twice. With III, the first three return to their state. Seek a combination touching every relay an odd number of times.'),P('II puis III puis IV : tous les relais sont éteints. L’ordre de ces trois leviers est libre. Tester et valider.','II then III then IV: all relays are off. These three levers may be used in any order. Test and validate.'),[1,2,3,98],masks=[11,22,37,12],initial_mask=63,goal_mask=0)
