l.notes(1,[(33,1),(1,9)],[P('FAIT : observation directement établie, y compris une limite constatée. HYPOTHÈSE : interprétation possible qui demande encore une preuve. INCONNU : aucune donnée permettant de répondre.','FACT: directly established observation, including an observed limit. HYPOTHESIS: possible interpretation still requiring proof. UNKNOWN: no data to answer.'),P('Le journal contient : une fenêtre allumée ; aucune image de la pièce ; une hypothèse de dîner ; volets fermés après la sirène ; aucune prévision fiable pour demain ; une hypothèse de peur.','The log contains: a lit window; no image of the room; a dinner hypothesis; shutters closing after the siren; no reliable forecast for tomorrow; a fear hypothesis.')])
