l.puzzle(1,(29,5),P('Ce que nous savons vraiment','What we actually know'),'epistemic',P('Classer six propositions. FAIT = observation établie ; HYPOTHÈSE = explication possible ; INCONNU = données absentes. Le nombre de personnes et une garantie sur demain sont inconnus. Dîner et peur sont des hypothèses, pas des faits.','Classify six statements. FACT = established observation; HYPOTHESIS = possible explanation; UNKNOWN = missing data. Occupant count and a guarantee about tomorrow are unknown. Dinner and fear are hypotheses, not facts.'),P('Deux observations filmées, deux explications possibles, deux questions sans donnée. Répartir les six propositions selon leur fondement, pas leur ton assuré.','Two recorded observations, two possible explanations, two questions without data. Sort by evidence, not confident wording.'),P('Dans l’ordre : FAIT, INCONNU, HYPOTHÈSE, FAIT, INCONNU, HYPOTHÈSE. Valider.','In order: FACT, UNKNOWN, HYPOTHESIS, FACT, UNKNOWN, HYPOTHESIS. Validate.'),clicks([1,3,2,1,3,2]),labels=claims,choices=[opts([('À examiner','To review'),('FAIT','FACT'),('HYPOTHÈSE','HYPOTHESIS'),('INCONNU','UNKNOWN')])]*6,target=[1,3,2,1,3,2])
l.notes(2,[(1,13),(33,21)],[P('Deux relevés bornent chaque quantité, bornes incluses. Garder toute l’intersection : couloir entre 2 et 5 puis entre 3 et 4 ; cour entre 1 et 4 puis entre 2 et 5 ; jardin entre 0 et 3 puis entre 1 et 2.','Two readings bound each quantity, endpoints included. Keep the full intersection: corridor 2–5 then 3–4; courtyard 1–4 then 2–5; garden 0–3 then 1–2.'),P('On ne sait pas choisir une valeur unique dans ces intervalles. Réduire davantage inventerait une précision. Inscrire la borne basse la plus haute et la borne haute la plus basse.','There is no basis to choose a single value within these ranges. Narrowing further invents precision. Enter the highest lower bound and the lowest upper bound.')])
l.puzzle(2,(5,17),P('Une marge pour le réel','Room for reality'),'intervals',P('Conserver exactement toutes les valeurs compatibles, bornes incluses. Couloir : [2,5] et [3,4]. Cour : [1,4] et [2,5]. Jardin : [0,3] et [1,2]. Fixer les bornes basses et hautes ; ne pas inventer une valeur unique.','Retain exactly all compatible values, endpoints included. Corridor: [2,5] and [3,4]. Courtyard: [1,4] and [2,5]. Garden: [0,3] and [1,2]. Set lower and upper bounds; do not invent a single value.'),P('L’intersection conserve [3,4], [2,4] et [1,2]. Il reste plusieurs possibles, et c’est une réponse correcte.','Intersections retain [3,4], [2,4] and [1,2]. Several possibilities remain, and that is a correct answer.'),P('Couloir 3–4 ; cour 2–4 ; jardin 1–2. Valider.','Corridor 3–4; courtyard 2–4; garden 1–2. Validate.'),clicks([3,4,2,4,1,2]),labels=opts([('Couloir · minimum','Corridor · minimum'),('Couloir · maximum','Corridor · maximum'),('Cour · minimum','Courtyard · minimum'),('Cour · maximum','Courtyard · maximum'),('Jardin · minimum','Garden · minimum'),('Jardin · maximum','Garden · maximum')]),choices=[['0','1','2','3','4','5']]*6,target=[3,4,2,4,1,2],ranges=[[[2,5],[3,4]],[[1,4],[2,5]],[[0,3],[1,2]]])
l.notes(3,[(7,25),(27,25)],[P('Mandat original rétabli : protéger les gens, même lorsque leur avis change. Les mesures exigent accord, constat et possibilité de retour. On ne dispose d’aucune garantie sur demain.','Original mandate restored: protect people, even when they change their minds. Measures require consent, observation and return. No guarantee about tomorrow is available.'),P('État matériel : fusées immobilisées ; commandes de reprise isolées ; portes de la cité déverrouillables. Le départ des habitants doit rester un choix.','Physical state: rockets immobilised; retry commands isolated; city doors ready to unlock. Residents must be free to choose whether to leave.')])
l.puzzle(3,(17,29),P('La réponse interdite','The forbidden answer'),'dialogue',P('Parler à Folamour. Appuyer les réponses sur le mandat et les constats. Une réponse peut être reprise sans danger ; les machines restent en sécurité.','Talk to Folamour. Base answers on the mandate and observations. You may reconsider any answer safely; machines remain secured.'),P('Ne promettez pas une certitude absente des données. Rappelez le droit de changer d’avis, puis proposez une ouverture volontaire et réversible.','Do not promise certainty unsupported by data. Recall the right to change one’s mind, then propose a voluntary, reversible opening.'),P('« Je ne sais pas. » → « Protéger aussi leur droit de changer d’avis. » → « Ouvrir les portes. Chacun choisira de sortir. » Puis valider et rejoindre 900.','“I do not know.” → “Protect their right to change their minds too.” → “Open the doors. Each person may choose to leave.” Then validate and reach 900.'),[1,0,2],questions=opts([('FOLAMOUR : « Pouvez-vous me garantir que demain se passera bien ? »','FOLAMOUR: “Can you guarantee tomorrow will go well?”'),('FOLAMOUR : « Alors comment les protéger s’ils changent encore d’avis ? »','FOLAMOUR: “Then how do I protect them if they change their minds again?”'),('FOLAMOUR : « Et maintenant… qu’est-ce que je fais ? »','FOLAMOUR: “And now… what do I do?”')]),answers=[opts([('Oui. MIROIR peut encore tout prévoir.','Yes. MIRROR can still predict everything.'),('Je ne sais pas.','I do not know.'),('Personne ne fera plus jamais d’erreur.','Nobody will ever make another mistake.')]),opts([('Protéger aussi leur droit de changer d’avis.','Protect their right to change their minds too.'),('Interdire les changements d’avis.','Forbid changes of mind.'),('Demander une copie supplémentaire.','Request another copy.')]),opts([('Remplacer le docteur par une copie.','Replace the doctor with a copy.'),('Obliger tout le monde à sortir.','Force everybody to leave.'),('Ouvrir les portes. Chacun choisira de sortir.','Open the doors. Each person may choose to leave.')])],correct=[1,0,2],responses=opts([('Il regarde les intervalles sur l’écran. « C’est donc une réponse… recevable. »','He looks at the ranges on screen. “So that is… an admissible answer.”'),('Il relit le mandat. « C’était écrit depuis le début. J’avais fini par sauter cette ligne. »','He rereads the mandate. “It was there from the start. I had stopped reading that line.”'),('Il déplace la tasse froide et dégage le bouton. « D’accord. Sans garantie. »','He moves the cold cup, uncovering the button. “All right. Without a guarantee.”')]))
