# Rebuild the gantry walkthrough with physical inspections before certification.
n=21;E=json.loads((D/f'events{n}.json').read_text());by={e['id']:e for e in E};m=json.loads((D/f'maze{n}.json').read_text());F={(x,y) for y,row in enumerate(m['grid']) for x,v in enumerate(row) if v}
regular=[s['id'] for s in json.loads((T/f'route_level{n}.json').read_text()) if '_obs' not in s['id']]
done=set();current=tuple(m['start']);settings=[1,2,0];route=[]
def walk_to(id,configure=None):
 global current
 e=by[id];closed={tuple(t['cell']) for t in E if t['kind'] in ['door','exit'] and t['id'] not in done}
 if 'c21_p1' not in done:closed|={tuple(b['cell']) for b in gantry['world_gates'] if settings[b['channel']] not in b['allowed']}
 targets=set(neighbours(tuple(e['cell']))) if e['kind']=='exit' else {tuple(e['cell'])}
 p=path(current,targets,F-closed);assert p,(id,current,settings)
 s=dict(id=id,route=p);current=p[-1]
 if configure is not None:s['configure']=configure
 else:done.add(id);done.update(e.get('opens',[]))
 route.append(s)
for id in regular:
 if id=='c21_p1':
  acts=[1,2,2];walk_to(id,acts)
  for a in acts:
   settings=[(v+gantry['masks'][a][i])%3 for i,v in enumerate(settings)]
  assert settings==[0,0,0]
  for ob in gantry['observations']:walk_to(ob)
 walk_to(id)
save(T/'route_level21.json',route)

